"""Load embedded data files from the zipapp."""
import os
import sys
import json

# Paths relative to this module
_DATA_DIR = os.path.join(os.path.dirname(__file__), "data")


def _read_text(name):
    """Read a text file from the data directory.

    Works both when running from a zipapp and when running from a normal
    filesystem layout.
    """
    try:
        with open(os.path.join(_DATA_DIR, name), "rb") as f:
            return f.read().decode("utf-8")
    except (FileNotFoundError, NotADirectoryError):
        # Zipapp context - use importlib.resources
        try:
            from importlib.resources import files
            return files(__package__).joinpath("data", name).read_text(
                encoding="utf-8"
            )
        except Exception:
            raise


def text(name):
    return _read_text(name)


def json_text(name):
    # Return the raw text of a JSON resource (preserves formatting)
    return _read_text(name)


def json_data(name):
    return json.loads(_read_text(name))
PYEOF

